import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { escapeTableCell, readCatalogModel } from './lib/skill-catalog.mjs';
import { repoRoot } from './lib/repo.mjs';

export function buildSkillsCatalogMarkdown() {
  const { manifest, skillMap } = readCatalogModel();

  const lines = [
    '# Skills catalog',
    '',
    '> Generated by `npm run catalog:generate`.',
    '',
    `Total skills: ${skillMap.size}`,
    '',
  ];

  manifest.groupings.forEach((group, index) => {
    lines.push(`## ${group.title}`, '', group.description, '', '| Skill | Description | Version | Install | Status |', '|---|---|---|---|---|');
    for (const skillName of group.skills) {
      const skill = skillMap.get(skillName);
      const status = skill.deprecated ? `deprecated; use ${skill.replaced_by}` : 'active';
      lines.push(`| [${skillName}](../skills/${skillName}/SKILL.md) | ${escapeTableCell(skill.description)} | ${skill.version ?? ''} | ${skill.install_scope ?? ''} | ${status} |`);
    }
    if (index < manifest.groupings.length - 1) {
      lines.push('');
    }
  });

  return `${lines.join('\n')}\n`;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const outPath = path.join(repoRoot, 'docs', 'skills-catalog.md');
  fs.writeFileSync(outPath, buildSkillsCatalogMarkdown());
  console.log(`✓ generated ${path.relative(repoRoot, outPath)}`);
}
